const crypto = require('crypto');

const request = $input.first().json;
const headers = request.headers ?? {};
const body = request.body ?? {};

// ============================================================
// CONFIGURACIÓN DE PRUEBA
// Cambia estos valores antes de activar el workflow.
// NO uses estos valores de ejemplo en producción.
// ============================================================
const CLIENT_ID = 'salesforce_preprod';
const CLIENT_SECRET = '${REDACTED_SECRET}';
const JWT_SECRET = '${REDACTED_SECRET}';
const ISSUER = 'https://quicklink.bkn.aigentss.cloud';
const AUDIENCE = 'aigentss-api';
const ALLOWED_SCOPE = 'salesforce.integration';
const EXPIRES_IN_SECONDS = 900;

function safeEqual(a, b) {
  const first = Buffer.from(String(a ?? ''), 'utf8');
  const second = Buffer.from(String(b ?? ''), 'utf8');

  if (first.length !== second.length) {
    return false;
  }

  return crypto.timingSafeEqual(first, second);
}

function base64UrlJson(value) {
  return Buffer.from(JSON.stringify(value), 'utf8').toString('base64url');
}

function signJwt(payload, secret) {
  const encodedHeader = base64UrlJson({
    alg: 'HS256',
    typ: 'JWT',
  });

  const encodedPayload = base64UrlJson(payload);
  const signingInput = `${encodedHeader}.${encodedPayload}`;

  const signature = crypto
    .createHmac('sha256', secret)
    .update(signingInput)
    .digest('base64url');

  return `${signingInput}.${signature}`;
}

function oauthError(statusCode, error, description) {
  return [{
    json: {
      statusCode,
      body: {
        error,
        error_description: description,
      },
    },
  }];
}

let clientId = body.client_id;
let clientSecret = body.client_secret;

// Salesforce normalmente puede enviar client_id/client_secret con HTTP Basic.
const authorization = headers.authorization ?? headers.Authorization ?? '';

if (typeof authorization === 'string' && authorization.startsWith('Basic ')) {
  try {
    const decoded = Buffer
      .from(authorization.slice(6).trim(), 'base64')
      .toString('utf8');

    const separatorIndex = decoded.indexOf(':');

    if (separatorIndex >= 0) {
      clientId = decoded.slice(0, separatorIndex);
      clientSecret = decoded.slice(separatorIndex + 1);
    }
  } catch {
    return oauthError(401, 'invalid_client', 'La cabecera Basic no es válida.');
  }
}

if (body.grant_type !== 'client_credentials') {
  return oauthError(
    400,
    'unsupported_grant_type',
    'grant_type debe ser client_credentials.',
  );
}

if (!safeEqual(clientId, CLIENT_ID) || !safeEqual(clientSecret, CLIENT_SECRET)) {
  return oauthError(
    401,
    'invalid_client',
    'El client_id o client_secret no es válido.',
  );
}

const requestedScope = body.scope || ALLOWED_SCOPE;

if (requestedScope !== ALLOWED_SCOPE) {
  return oauthError(
    400,
    'invalid_scope',
    `El único scope permitido es ${ALLOWED_SCOPE}.`,
  );
}

const now = Math.floor(Date.now() / 1000);

const payload = {
  iss: ISSUER,
  sub: CLIENT_ID,
  aud: AUDIENCE,
  scope: ALLOWED_SCOPE,
  environment: 'preproduction',
  iat: now,
  nbf: now,
  exp: now + EXPIRES_IN_SECONDS,
  jti: crypto.randomUUID(),
};

const accessToken = signJwt(payload, JWT_SECRET);

return [{
  json: {
    statusCode: 200,
    body: {
      access_token: accessToken,
      token_type: 'Bearer',
      expires_in: EXPIRES_IN_SECONDS,
      scope: ALLOWED_SCOPE,
    },
  },
}];

const crypto = require('crypto');

const request = $input.first().json;
const headers = request.headers ?? {};
const body = request.body ?? {};

// Deben ser exactamente los mismos valores del nodo "Emitir JWT".
const JWT_SECRET = '${REDACTED_SECRET}';
const EXPECTED_ISSUER = 'https://quicklink.bkn.aigentss.cloud';
const EXPECTED_AUDIENCE = 'aigentss-api';
const REQUIRED_SCOPE = 'salesforce.integration';
const CLOCK_TOLERANCE_SECONDS = 30;

function response(statusCode, responseBody) {
  return [{
    json: {
      statusCode,
      body: responseBody,
    },
  }];
}

function unauthorized(description) {
  return response(401, {
    error: 'invalid_token',
    error_description: description,
  });
}

function safeEqualBuffers(first, second) {
  if (first.length !== second.length) {
    return false;
  }

  return crypto.timingSafeEqual(first, second);
}

function decodeJsonPart(encodedPart) {
  return JSON.parse(
    Buffer.from(encodedPart, 'base64url').toString('utf8'),
  );
}

const authorization = headers.authorization ?? headers.Authorization ?? '';

if (typeof authorization !== 'string' || !authorization.startsWith('Bearer ')) {
  return unauthorized(
    'Debes enviar Authorization: Bearer <access_token>.',
  );
}

const token = authorization.slice(7).trim();
const parts = token.split('.');

if (parts.length !== 3) {
  return unauthorized('El JWT no tiene una estructura válida.');
}

const [encodedHeader, encodedPayload, encodedSignature] = parts;

let jwtHeader;
let payload;

try {
  jwtHeader = decodeJsonPart(encodedHeader);
  payload = decodeJsonPart(encodedPayload);
} catch {
  return unauthorized('No se pudo decodificar el JWT.');
}

if (jwtHeader.alg !== 'HS256') {
  return unauthorized('El algoritmo del JWT no está permitido.');
}

const signingInput = `${encodedHeader}.${encodedPayload}`;

const expectedSignature = crypto
  .createHmac('sha256', JWT_SECRET)
  .update(signingInput)
  .digest();

let receivedSignature;

try {
  receivedSignature = Buffer.from(encodedSignature, 'base64url');
} catch {
  return unauthorized('La firma del JWT no tiene un formato válido.');
}

if (!safeEqualBuffers(receivedSignature, expectedSignature)) {
  return unauthorized('La firma del JWT no es válida.');
}

const now = Math.floor(Date.now() / 1000);

if (
  typeof payload.nbf === 'number' &&
  now + CLOCK_TOLERANCE_SECONDS < payload.nbf
) {
  return unauthorized('El JWT todavía no es válido.');
}

if (
  typeof payload.exp !== 'number' ||
  now - CLOCK_TOLERANCE_SECONDS >= payload.exp
) {
  return unauthorized('El JWT está vencido o no contiene exp.');
}

if (payload.iss !== EXPECTED_ISSUER) {
  return unauthorized('El issuer del JWT no es válido.');
}

const audiences = Array.isArray(payload.aud) ? payload.aud : [payload.aud];

if (!audiences.includes(EXPECTED_AUDIENCE)) {
  return unauthorized('El audience del JWT no es válido.');
}

const scopes = String(payload.scope ?? '')
  .split(/\s+/)
  .filter(Boolean);

if (!scopes.includes(REQUIRED_SCOPE)) {
  return response(403, {
    error: 'insufficient_scope',
    error_description: `El token necesita el scope ${REQUIRED_SCOPE}.`,
  });
}

// Aquí comienza la lógica real de tu endpoint protegido.
return response(200, {
  ok: true,
  message: 'Token válido. El endpoint protegido fue ejecutado.',
  authenticated_client: payload.sub,
  environment: payload.environment,
  token_id: payload.jti,
  received_body: body,
});
